def isleap(y):
    if y % 4000 == 0:
        return False
    if y % 400 == 0:
        return True
    if y % 100 == 0:
        return False
    return y % 4 == 0

def dayno(y, m, d):
    ml = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    s = 0
    for yy in range(1, y):
        if isleap(yy):
            s += 366
        else:
            s += 365
    for mm in range(1, m):
        s += ml[mm - 1]
        if mm == 2 and isleap(y):
            s += 1
    return s + d

def f(p):
    return dayno(p['y2'], p['m2'], p['d2']) - dayno(p['y1'], p['m1'], p['d1'])

def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def f(p):
    n = p['n']
    a = p['a']
    k = len(a)
    total = 0
    for mask in range(1, 2 ** k):
        l = 1
        bits = 0
        for i in range(k):
            if (mask // 2 ** i) % 2 == 1:
                l = l * a[i] // gcd(l, a[i])
                bits += 1
        if bits % 2 == 1:
            total += n // l
        else:
            total -= n // l
    prod = 1
    for x in a:
        prod *= x
    return total - n // prod

def f(p):
    w = p['w']
    d = p['d']
    a = p['a']
    t = p['t']
    free = [0] * w
    res = 0
    for i in range(len(a)):
        best = -1
        for j in range(w):
            if free[j] <= a[i]:
                best = j
                break
        if best >= 0:
            start = a[i]
        else:
            best = 0
            for j in range(1, w):
                if free[j] < free[best]:
                    best = j
            start = free[best]
        if start - a[i] > d:
            continue
        free[best] = start + t[i]
        res += (i + 1) * (best + 1)
    return res

def f(p):
    L = p['L']
    xs = p['xs']
    ds = p['ds']
    n = len(xs)
    lt = []
    rt = []
    for i in range(n):
        if ds[i] == -1:
            lt.append(xs[i])
        else:
            rt.append(L - xs[i])
    lt.sort()
    rt.sort()
    T = []
    for t in lt:
        T.append(t)
    for t in reversed(rt):
        T.append(t)
    s = 0
    for i in range(n):
        s += (i + 1) * T[i]
    return s

def f(p):
    xs = list(p['xs'])
    t = p['t']
    n = len(xs)
    for _ in range(t):
        nw = []
        for i in range(n):
            if i == 0:
                nw.append((xs[0] + xs[1]) // 2)
            elif i == n - 1:
                nw.append((xs[n - 2] + xs[n - 1]) // 2)
            else:
                nw.append((xs[i - 1] + xs[i] + xs[i + 1]) // 3)
        xs = nw
    return sum(xs)
